-- Categories (from the real catalog structure)
INSERT OR IGNORE INTO categories (slug, name_ar, name_en, description_ar, image, sort_order, active) VALUES
  ('bedrooms', 'غرف النوم والأجنحة الفندقية', 'Bedrooms & Hotel Suites', 'غرف نوم وأجنحة فندقية بتصاميم عصرية وكلاسيكية تناسب الفنادق والشقق الفندقية.', '/static/images/bedroom-1.jpg', 1, 1),
  ('living-lobby', 'أثاث اللوبي والمعيشة', 'Living & Lobby Furniture', 'أطقم معيشة ولوبي فاخرة تناسب استقبالات الفنادق والمنتجعات.', '/static/images/living-lux.jpg', 2, 1),
  ('dining', 'غرف الطعام والمطاعم', 'Dining & Restaurants', 'طاولات وكراسي وبوفيهات لغرف الطعام والمطاعم والكافيهات.', '/static/images/dining-1.jpg', 3, 1),
  ('office', 'أثاث المكاتب ومساحات العمل', 'Office & Workspace', 'حلول أثاث مكتبي لمساحات العمل الإدارية في الفنادق والمنشآت.', '/static/images/office-1.jpg', 4, 1),
  ('storage', 'حلول التخزين', 'Storage Solutions', 'وحدات تخزين ذكية ودواليب وخزائن بتصاميم عملية.', '/static/images/storage-1.jpg', 5, 1),
  ('outdoor', 'الأثاث الخارجي', 'Outdoor Furniture', 'أثاث خارجي للحدائق والتراسات والمسابح في الفنادق والمنتجعات.', '/static/images/outdoor-1.jpg', 6, 1);

-- Products (real images from catalog, descriptions describe what's shown - no invented prices)
INSERT OR IGNORE INTO products (slug, name_ar, name_en, short_desc_ar, description_ar, category_id, main_image, featured, is_new, status, sort_order) VALUES
  ('hotel-bedroom-classic-gold', 'غرفة نوم فندقية كلاسيك', 'Classic Hotel Bedroom Set', 'غرفة نوم كاملة بتشطيب فاخر تناسب الأجنحة الفندقية.', 'غرفة نوم فندقية متكاملة تشمل السرير والدولاب والتسريحة والكمودينو، بتصميم كلاسيكي فاخر وخامات عالية الجودة مناسبة للفنادق والأجنحة.', 1, '/static/images/bedroom-1.jpg', 1, 0, 'published', 1),
  ('hotel-bedroom-modern-wood', 'غرفة نوم فندقية خشبية مودرن', 'Modern Wooden Hotel Bedroom', 'غرفة نوم بخامات خشبية دافئة وتصميم عصري.', 'غرفة نوم بتصميم عصري وخامات خشبية طبيعية، مثالية للشقق الفندقية والمنتجعات التي تبحث عن طابع دافئ وأنيق.', 1, '/static/images/bedroom-2.jpg', 1, 0, 'published', 2),
  ('hotel-bedroom-suite', 'جناح نوم فندقي', 'Hotel Bedroom Suite', 'جناح نوم متكامل بإضاءة وتفاصيل فندقية.', 'جناح نوم فندقي بتصميم متكامل يشمل وحدات الإضاءة والتخزين، مصمم لتجربة إقامة مريحة وفاخرة.', 1, '/static/images/bedroom-3.jpg', 0, 1, 'published', 3),
  ('twin-room-set', 'غرفة توين للفنادق', 'Twin Hotel Room Set', 'سريران منفصلان بتصميم عملي للغرف الفندقية.', 'غرفة توين بسريرين منفصلين وتشطيبات عملية سهلة الصيانة، مناسبة للفنادق والشقق الفندقية.', 1, '/static/images/bedroom-twin.jpg', 0, 0, 'published', 4),
  ('kids-bunk-room', 'غرفة أطفال بسرير بطابقين', 'Kids Bunk Bed Room', 'حلول غرف أطفال عملية للمنتجعات والشقق العائلية.', 'غرفة أطفال بسرير بطابقين مع وحدات تخزين مدمجة، تصميم آمن وعملي يناسب الوحدات العائلية في المنتجعات.', 1, '/static/images/kids-bunk-1.jpg', 0, 0, 'published', 5),
  ('classic-wardrobe-white', 'دولاب كلاسيك أبيض', 'Classic White Wardrobe', 'دولاب بتصميم كلاسيكي وتفاصيل راقية.', 'دولاب كلاسيكي بأبواب مزخرفة وتشطيب أبيض فاخر، يضيف لمسة أناقة للغرف الفندقية.', 5, '/static/images/wardrobe-classic.jpg', 0, 0, 'published', 6),
  ('dressing-unit', 'وحدة تسريحة بمرآة', 'Dressing Unit with Mirror', 'تسريحة عملية بمرآة ووحدات أدراج.', 'وحدة تسريحة بمرآة كاملة وأدراج تخزين، تصميم عملي يناسب الغرف الفندقية والشقق.', 1, '/static/images/dressing-1.jpg', 0, 0, 'published', 7),
  ('lobby-sofa-modern', 'أطقم جلوس مودرن للوبي', 'Modern Lobby Seating', 'أطقم كنب عصرية لمناطق الاستقبال.', 'أطقم جلوس عصرية بخطوط نظيفة وخامات مريحة، مصممة لمناطق الاستقبال واللوبي في الفنادق.', 2, '/static/images/living-1.jpg', 1, 0, 'published', 8),
  ('living-set-luxury', 'طقم معيشة فاخر', 'Luxury Living Set', 'طقم معيشة فاخر بتفاصيل كلاسيكية.', 'طقم معيشة فاخر بتنجيد راقٍ وتفاصيل كلاسيكية، يناسب الأجنحة الرئاسية ومناطق الضيافة المميزة.', 2, '/static/images/living-lux.jpg', 1, 0, 'published', 9),
  ('royal-majlis-set', 'طقم مجلس ملكي', 'Royal Majlis Set', 'مجلس فاخر بطراز ملكي للمساحات المميزة.', 'طقم مجلس بطراز ملكي فاخر وتنجيد مميز، مثالي لقاعات كبار الزوار ومناطق الضيافة الفاخرة.', 2, '/static/images/living-royal.jpg', 0, 0, 'published', 10),
  ('classic-salon', 'صالون كلاسيك', 'Classic Salon', 'صالون كلاسيكي أنيق لمناطق الاستقبال.', 'صالون كلاسيكي بتفاصيل أنيقة، يناسب الاستقبالات والمساحات شبه الرسمية في المنشآت الفندقية.', 2, '/static/images/living-classic.jpg', 0, 0, 'published', 11),
  ('dining-set-modern', 'طقم سفرة مودرن', 'Modern Dining Set', 'طاولة طعام وكراسي بتصميم عصري.', 'طقم سفرة عصري بخامات عالية الجودة، مناسب لمطاعم الفنادق وغرف الطعام الخاصة.', 3, '/static/images/dining-1.jpg', 1, 0, 'published', 12),
  ('dining-set-premium', 'سفرة فاخرة', 'Premium Dining Set', 'سفرة فاخرة لغرف طعام مميزة.', 'طقم سفرة فاخر بتشطيبات مميزة، يناسب المطاعم الراقية وقاعات الطعام في الفنادق.', 3, '/static/images/dining-2.jpg', 0, 1, 'published', 13),
  ('buffet-classic', 'بوفيه كلاسيك', 'Classic Buffet', 'بوفيه كلاسيكي بتفاصيل خشبية راقية.', 'بوفيه كلاسيكي بمرآة وتفاصيل خشبية مشغولة، قطعة مميزة لغرف الطعام الفاخرة.', 3, '/static/images/buffet-classic.jpg', 0, 0, 'published', 14),
  ('crockery-unit', 'وحدة عرض أطباق', 'Crockery Display Unit', 'وحدة عرض بإضاءة مدمجة للأطباق والتحف.', 'وحدة عرض أنيقة بإضاءة مدمجة لعرض الأطباق والتحف في المطاعم وغرف الطعام.', 3, '/static/images/crockery.jpg', 0, 0, 'published', 15),
  ('office-desk-executive', 'مكتب إداري', 'Executive Office Desk', 'مكتب إداري بتصميم عملي وأنيق.', 'مكتب إداري بخامات خشبية عالية الجودة وتصميم عملي، يناسب المكاتب الإدارية في الفنادق والشركات.', 4, '/static/images/office-1.jpg', 0, 0, 'published', 16),
  ('workspace-solutions', 'حلول مساحات العمل', 'Workspace Solutions', 'تجهيز متكامل لمساحات العمل المشتركة.', 'حلول متكاملة لتجهيز مساحات العمل المشتركة والمكاتب الإدارية بأثاث عملي ومريح.', 4, '/static/images/office-3.jpg', 0, 0, 'published', 17),
  ('smart-storage-table', 'طاولة تخزين ذكية', 'Smart Storage Table', 'طاولة متعددة الاستخدامات بتخزين مدمج.', 'طاولة ذكية قابلة للرفع مع مساحات تخزين مدمجة، حل عملي للمساحات المحدودة في الشقق الفندقية.', 5, '/static/images/storage-smart.jpg', 0, 1, 'published', 18),
  ('storage-shelving', 'وحدات أرفف تخزين', 'Storage Shelving Units', 'أرفف تخزين خشبية بتصميم مرن.', 'وحدات أرفف خشبية بتكوينات مرنة، تناسب المكتبات ومناطق العرض والتخزين.', 5, '/static/images/storage-3.jpg', 0, 0, 'published', 19),
  ('outdoor-lounge', 'جلسة خارجية', 'Outdoor Lounge Set', 'جلسات خارجية مريحة للحدائق والتراسات.', 'جلسة خارجية بخامات مقاومة للعوامل الجوية، مثالية لحدائق الفنادق والتراسات ومناطق المسابح.', 6, '/static/images/outdoor-1.jpg', 1, 0, 'published', 20),
  ('outdoor-garden-set', 'طقم حديقة', 'Garden Furniture Set', 'أطقم حدائق متكاملة للمنتجعات.', 'طقم حديقة متكامل بتصميم مريح وخامات معالجة، يناسب المساحات الخارجية في المنتجعات والفنادق.', 6, '/static/images/outdoor-2.jpg', 0, 0, 'published', 21);

