-- Services (from catalog "what we offer": Custom Furniture Design, Interior Styling & Consultation, Delivery & Assembly, Space Planning Solutions, After-Sales Support, Furniture Warranty, Renovation & Makeover)
INSERT OR IGNORE INTO services (slug, title_ar, title_en, short_desc_ar, description_ar, icon, image, sort_order, active) VALUES
  ('custom-design', 'تصميم أثاث حسب الطلب', 'Custom Furniture Design', 'تصميم وتنفيذ أثاث مخصص حسب احتياجات مشروعك.', 'نصمم وننفذ أثاثاً مخصصاً يلبي متطلبات مشروعك الفندقي من حيث المقاسات والخامات والطراز، مع الالتزام بهوية المشروع.', 'fa-pencil-ruler', '/static/images/desk-unit.jpg', 1, 1),
  ('interior-consultation', 'استشارات التصميم الداخلي', 'Interior Styling & Consultation', 'استشارات متخصصة في تنسيق وتجهيز المساحات.', 'نقدم استشارات متخصصة في التصميم الداخلي وتنسيق المساحات الفندقية لتحقيق أفضل تجربة للنزلاء.', 'fa-comments', '/static/images/living-2.jpg', 2, 1),
  ('delivery-assembly', 'التوريد والتركيب', 'Delivery & Assembly', 'توصيل وتركيب احترافي في موقع المشروع.', 'فريق متخصص للتوصيل والتركيب في موقع المشروع مع الالتزام بالجداول الزمنية ومعايير الجودة.', 'fa-truck', '/static/images/storage-2.jpg', 3, 1),
  ('space-planning', 'حلول تخطيط المساحات', 'Space Planning Solutions', 'تخطيط ذكي للمساحات لتحقيق أقصى استفادة.', 'ندرس المساحات ونضع حلول توزيع الأثاث المثلى لتحقيق أقصى استفادة وظيفية وجمالية من كل متر.', 'fa-vector-square', '/static/images/office-4.jpg', 4, 1),
  ('after-sales', 'دعم ما بعد البيع', 'After-Sales Support', 'خدمة ودعم مستمر بعد التسليم.', 'نوفر دعماً مستمراً بعد التسليم يشمل الصيانة والمتابعة لضمان استمرارية الجودة.', 'fa-headset', '/static/images/living-3.jpg', 5, 1),
  ('renovation', 'التجديد وإعادة التأهيل', 'Renovation & Makeover', 'تجديد وتحديث المساحات الفندقية القائمة.', 'نقدم خدمات تجديد وإعادة تأهيل للمنشآت الفندقية القائمة لتحديث مظهرها ورفع كفاءتها التشغيلية.', 'fa-paint-roller', '/static/images/niche-1.jpg', 6, 1);

