-- Homepage sections
INSERT OR IGNORE INTO home_sections (section_key, title_ar, title_en, content_ar, content_en, image, cta_text_ar, cta_url, sort_order, active) VALUES
  ('hero', 'أثاث فندقي يليق بمشروعك', 'Hospitality Furniture Worthy of Your Project', 'سرايا الأندلس توفر حلول أثاث وتجهيز متكاملة للمشروعات الفندقية والضيافة — جودة، تصميم، وتنفيذ حسب احتياجات المشروع.', 'Saraya Al-Andalus provides integrated furniture and fit-out solutions for hospitality projects.', '/static/images/hero-living.jpg', 'استكشف منتجاتنا', '/products', 1, 1),
  ('about', 'من نحن', 'About Us', 'سرايا الأندلس للأثاث الفندقي والضيافة — نعمل في مجال تجهيز الفنادق والشقق الفندقية والمنتجعات بحلول أثاث متكاملة تجمع بين الجودة والتصميم والعملية، مع تنفيذ مخصص حسب احتياجات كل مشروع.', NULL, '/static/images/living-lux.jpg', 'اعرف المزيد', '/about', 2, 1),
  ('categories', 'حلولنا وفئات منتجاتنا', 'Our Solutions', NULL, NULL, NULL, NULL, NULL, 3, 1),
  ('featured', 'منتجات مميزة', 'Featured Products', NULL, NULL, NULL, NULL, NULL, 4, 1),
  ('services', 'خدماتنا', 'Our Services', NULL, NULL, NULL, NULL, NULL, 5, 1),
  ('projects', 'مشاريعنا', 'Our Projects', NULL, NULL, NULL, NULL, NULL, 6, 1),
  ('why_us', 'لماذا سرايا الأندلس؟', 'Why Choose Us', NULL, NULL, NULL, NULL, NULL, 7, 1),
  ('cta', 'ابدأ مشروعك معنا', 'Start Your Project With Us', 'تواصل معنا الآن للحصول على عرض سعر مخصص لمشروعك الفندقي.', NULL, NULL, 'اطلب عرض سعر', '/quote', 8, 1);
